INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
(40001, 0, 0, 0, 0, 0, 0, 0, 0, 'Ah, mon, Shagu sent ya for his herbs? Mishiki wanted to send it as soon as possible, but ya see, we got a bit of a problem.', 0),
(40002, 0, 0, 0, 0, 0, 0, 0, 0, 'You\'ve returned, my friend! And with the herbs no less. Here\'s the payment I owe.', 0),
(40003, 0, 0, 0, 0, 0, 0, 0, 0, 'An eye-opener, isn\'t it, $N?$B$BYou now feel closer to the Earthmother than ever before.$B$BRejoice and be one with nature!', 0),
(40301, 0, 0, 0, 0, 0, 0, 0, 0, 'Jhawna sent you? Blessed be the ancestors. I haven\'t heard from her in a while!$B$BAnd she sent me a sack of her and the means to make it. Always treasure your friends, $N, not even distance stays in the way of true bonds.$B$BEnough melancholy, I got some coins for you and if you wait a while I can even offer you a loaf of bread!', 0),
(40363, 0, 0, 0, 0, 0, 0, 0, 0, 'Your kindness surprises me, $C. With the Galak\'s raid crippled, the tauren will be free to continue their peaceful lives.$B$BThere is still yet work to do if I am to earn their favor.', 0),
(40364, 0, 0, 0, 0, 0, 0, 0, 0, 'I have never heard such a strange tale and I struggle to believe it to be true. We have never known the centaur to be anything but beasts seeking our extinction. If she is yet true to her word, perhaps I can assist.', 0),
(40365, 0, 0, 0, 0, 0, 0, 0, 0, 'She had you retrieve the pelts of prairie wolves and did not tell you what I would need to do with them to earn their favor.$B$BAlthough I am not the most gifted in the ways of magic, I believe I have just the idea to solve their trial.', 0),
(40366, 0, 0, 0, 0, 0, 0, 0, 0, 'These pelts are of even finer quality than I expected, $N. The enchantment is almost as if it is naturally woven into the fabric itself and will serve to protect newborns through the harsh change of the seasons.$B$BWe will not deny Kherra the opportunity to prove herself further to us. We understand there is more to her than the average centaur. It will take time for her to be welcome in Bloodhoof Village, but I have to wonder... are there more like her?', 0),
(40445, 0, 0, 0, 0, 0, 0, 0, 0, 'Your actions have eased this troubled mind. We can now be more free with the wyvern and let them truly grow within this world, and for that, I must thank you.$B$BTake this, as a symbol of my thanks young one.', 0),
(40446, 0, 0, 0, 0, 0, 0, 0, 0, 'With your assistance Suntail Pass is made much safer for travel.$B$BPerhaps now the Quillboar will have learned a lesson, and the Spirit Walker\'s can resume their tasks in peace.', 0),
(40447, 0, 0, 0, 0, 0, 0, 0, 0, 'I have been expecting you, it seems that you were sent to aid us at a time of dire need. The spirits have sent you to aid me, and now I must aid you for your help.$B$BTake this, on behalf of the Spirit Walker\'s for allowing us to conduct what must be done.$B$BGo now, and walk softly friend.', 0),
(40535, 0, 0, 0, 0, 0, 0, 0, 0, 'You return, and with the meat. By which means you\'ve decided to obtain it, I will not question.$B$BNow, onto the real task.', 0),
(40536, 0, 0, 0, 0, 0, 0, 0, 0, 'Ah, blessed be the ancestors, you truly have potential.$B$BI haven\'t seen old Sunchaser pushed back like that for a long long time, you have my blessing, and his.$B$BOne final task remains.', 0),
(40537, 0, 0, 0, 0, 0, 0, 0, 0, 'Gorgeous, just gorgeous.$B$BThe Earthmother truly had blessed this harpy with beautiful feathers, a pity her life ended. Yet, as the cycle of life and death continues one must always remember that our actions always lead to a greater purpose.$B$B<Tokala ties the feather in the wyvern cub\'s hair. The cub eagerly makes its way into your backpack, ready to face the world together with you.>', 0),
(40584, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh? Wait, that is my leaf! Did someone send you to find me? I appreciate it! My name is Melyndella. I have no time to chat though, things are bad! Kaylee was poisoned by Centaurs.', 0),
(40585, 0, 0, 0, 0, 0, 0, 0, 0, 'You need an antidote for Centaur poison? I\'m afraid my last batch was used days ago... Do not despair though, I may  still be able to help!', 0),
(40586, 0, 0, 0, 0, 0, 0, 0, 0, 'Well done, $C. I will now prepare an antidote for you.', 0),
(40587, 0, 0, 0, 0, 0, 0, 0, 0, 'Yay! This is amazing! Stand back, I will heal her to speed up the antidote\'s effect!', 0),
(40588, 0, 0, 0, 0, 0, 0, 0, 0, 'So you have not only earned the friendship of a Dryad, but saved someone in need? We are blessed to have a Dryad living among us, truthfully I am impressed with your deeds.$B$BI will make sure to inform the village and ensure that Melyndella is properly accommodated here. May the ancestors smile upon you, friend!', 0),
(42070, 0, 0, 0, 0, 0, 0, 0, 0, 'I understand the urgency of this request and I can surely feel for the Moonhoof heir. Were I in the same position I believe I would have done the same.', 0),
(42071, 0, 0, 0, 0, 0, 0, 0, 0, 'You bring news from the Moonwhisper Coast and a favor from both the heir of the Moonhoof and mine? Sit, then, share this pipe with me and speak.', 0),
(60138, 0, 0, 0, 0, 0, 0, 0, 0, 'You have overcome the greatest trial a Mulgore hunter can face, and you have emerged with greater strength – and wisdom – for your efforts.$B$BCarry it with you as you step further into the world, young $C, and honor the memory of the beasts you defeated by remembering their lessons.', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(40002, 0, 0, 'Mixed herbs give mixed feelings, friend!', 0),
(40003, 0, 0, 'Come on, my friend, sit down and take a toke.$B$BIt will be well worth it.', 0),
(40301, 0, 0, 'Come and rest for a while.', 0),
(40363, 0, 0, 'Is it done, $C? As an exile, this is my only chance to find acceptance in amongst others.', 0),
(40364, 0, 0, 'I see that you have something on your mind. Speak freely.', 0),
(40365, 0, 0, 'You\'ve returned and yet it seems as if there is more for us to work toward.', 0),
(40366, 0, 0, 'You\'ve returned. Was she sincere in her words?', 0),
(40445, 0, 0, 'Have you had any luck, child?', 0),
(40446, 0, 0, 'The Bristleback hold incredible disregard for nature, have the Quillboar been dealt with?', 0),
(40447, 0, 0, 'Without the proper instruments, we cannot conduct our ancient rites and passages.', 0),
(40535, 0, 0, 'If you fail to feed your wyvern, it will one day feast upon you.', 0),
(40536, 0, 0, 'All who seek to become windriders must first challenge an alpha.', 0),
(40537, 0, 0, 'Domination over the sky, my hooves are shaking.', 0),
(40584, 0, 0, 'Oh hello! It\'s urgent, it\'s really bad!', 0),
(40585, 0, 0, 'Hail friend, what is the matter?', 0),
(40586, 0, 0, 'Did you get them?', 0),
(40587, 0, 0, 'Oh it\'s you! Did you get it? Did you?', 0),
(40588, 0, 0, 'Welcome back young $C, it has been a while.', 0),
(42070, 0, 0, 'Welcome to Bloodhoof Village. Is there something you wish to tell me?', 0),
(42071, 0, 0, 'Come forth. This elder will listen.', 0),
(60138, 0, 0, 'The kodo wander Mulgore far and wide. You may need to search for some time to find the herd. Patience is one of the lessons of the hunt.', 0);
